  ('42ed5619-f0cb-4628-b950-225dc99216e3', '7e104704-d383-4b37-bb66-58954da2caf0', null, 'topic'::public.curated_course_node_type, 'Network Architecture, Layering, and Internet Design Principles', 'This opening unit gives students the mental model for how networks are organized. It explains why layered design makes a global Internet possible while still allowing technologies to evolve independently.', 0),
  ('e6377f5f-d1aa-4367-994a-88639f4f8018', '7e104704-d383-4b37-bb66-58954da2caf0', '42ed5619-f0cb-4628-b950-225dc99216e3', 'subtopic'::public.curated_course_node_type, 'Layering models', 'Students learn how OSI and TCP/IP models divide networking responsibilities. The gist is to know what each layer abstracts from the layers above and below.', 0),
