insert into public.curated_course_resources (course_id, kind, title, link_or_site, description, sort_order)
values
  ('7e104704-d383-4b37-bb66-58954da2caf0', 'textbook'::public.curated_course_resource_kind, 'Computer Networking: A Top-Down Approach', 'Pearson', 'Kurose and Ross. Leading text for application, transport, network, link, wireless, and security layers.', 0),
  ('7e104704-d383-4b37-bb66-58954da2caf0', 'textbook'::public.curated_course_resource_kind, 'Computer Networks', 'Pearson', 'Tanenbaum and Wetherall. Broad networking reference covering protocol layers, routing, transport, wireless, and applications.', 1),
  ('7e104704-d383-4b37-bb66-58954da2caf0', 'textbook'::public.curated_course_resource_kind, 'Computer Networks: A Systems Approach', 'Morgan Kaufmann', 'Peterson and Davie. Strong systems-oriented reference for implementation and design tradeoffs.', 2),
  ('7e104704-d383-4b37-bb66-58954da2caf0', 'textbook'::public.curated_course_resource_kind, 'TCP/IP Illustrated, Volume 1', 'Addison-Wesley', 'Stevens and Fall. Classic packet-level reference for TCP/IP behavior, diagnostics, and protocol details.', 3),
  ('7e104704-d383-4b37-bb66-58954da2caf0', 'textbook'::public.curated_course_resource_kind, 'Data and Computer Communications', 'Pearson', 'Stallings. Comprehensive communications text for transmission, LANs, routing, protocols, and security.', 4),
  ('7e104704-d383-4b37-bb66-58954da2caf0', 'textbook'::public.curated_course_resource_kind, 'High Performance Browser Networking', 'https://hpbn.co/', 'O''Reilly / Grigorik. Modern applied guide to HTTP, TLS, TCP, wireless, latency, and web performance.', 5),
  ('7e104704-d383-4b37-bb66-58954da2caf0', 'textbook'::public.curated_course_resource_kind, 'Network Security Essentials', 'Pearson', 'William Stallings. Useful supplement for TLS, IPsec, wireless security, firewalls, and intrusion detection.', 6),
  ('7e104704-d383-4b37-bb66-58954da2caf0', 'website'::public.curated_course_resource_kind, 'Computer Networking: A Top-Down Approach', 'https://gaia.cs.umass.edu/kurose_ross/index.php', 'Companion site with slides, labs, and supporting materials.', 7),
  ('7e104704-d383-4b37-bb66-58954da2caf0', 'website'::public.curated_course_resource_kind, 'Stanford CS144', 'https://cs144.github.io/', 'Systems-oriented networking course with TCP/IP and network programming projects.', 8),
  ('7e104704-d383-4b37-bb66-58954da2caf0', 'website'::public.curated_course_resource_kind, 'Beej''s Guide to Network Programming', 'https://beej.us/guide/bgnet/', 'Practical sockets guide for TCP, UDP, clients, servers, and networking APIs.', 9),
  ('7e104704-d383-4b37-bb66-58954da2caf0', 'website'::public.curated_course_resource_kind, 'IETF RFC Editor', 'https://www.rfc-editor.org/', 'Authoritative protocol specifications and standards documents.', 10),
  ('7e104704-d383-4b37-bb66-58954da2caf0', 'website'::public.curated_course_resource_kind, 'Wireshark Documentation', 'https://www.wireshark.org/docs/', 'Packet-analysis documentation and learning reference for protocol inspection.', 11),
  ('7e104704-d383-4b37-bb66-58954da2caf0', 'website'::public.curated_course_resource_kind, 'Cisco Networking Academy', 'https://www.netacad.com/', 'Structured networking, routing, switching, security, and hands-on lab resources.', 12),
  ('7e104704-d383-4b37-bb66-58954da2caf0', 'website'::public.curated_course_resource_kind, 'Mozilla MDN HTTP', 'https://developer.mozilla.org/en-US/docs/Web/HTTP', 'Clear reference for HTTP, headers, caching, and web protocols.', 13),
  ('7e104704-d383-4b37-bb66-58954da2caf0', 'website'::public.curated_course_resource_kind, 'Cloudflare Learning Center', 'https://www.cloudflare.com/learning/', 'Readable explanations of DNS, TLS, routing, CDN, DDoS, and security concepts.', 14),
  ('7e104704-d383-4b37-bb66-58954da2caf0', 'website'::public.curated_course_resource_kind, 'Zeek', 'https://zeek.org', 'Network security monitoring framework for protocol analysis and defensive labs.', 15),
  ('7e104704-d383-4b37-bb66-58954da2caf0', 'youtube'::public.curated_course_resource_kind, 'Computer Networking: A Top-Down Approach', 'https://www.youtube.com/@JimKurose', 'Author lectures supporting core networking concepts and textbook topics.', 16),
  ('7e104704-d383-4b37-bb66-58954da2caf0', 'youtube'::public.curated_course_resource_kind, 'Practical Networking', 'https://www.youtube.com/@PracticalNetworking', 'Clear explanations for TCP/IP, subnetting, routing, switching, and protocols.', 17),
  ('7e104704-d383-4b37-bb66-58954da2caf0', 'youtube'::public.curated_course_resource_kind, 'Ben Eater', 'https://www.youtube.com/@BenEater', 'Excellent hands-on networking and low-level computing explanations.', 18),
  ('7e104704-d383-4b37-bb66-58954da2caf0', 'youtube'::public.curated_course_resource_kind, 'David Bombal', 'https://www.youtube.com/@davidbombal', 'Networking, Cisco, Packet Tracer, Wireshark, and cybersecurity tutorials.', 19);
